              </dt>
              <dd className="text-2xl font-semibold text-foreground tabular-nums">
                {intFormat.format(system.annualProductionKwh)}
                <span className="text-base font-normal text-muted-foreground"> kWh a year</span>
              </dd>
            </div>
          </dl>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
